mapper.select:
select 
from preg_bag_item i
where i.del_flag = '0'

    and i.bag_id = #{bagId}


    and i.category = #{category}


    and i.prepared = #{prepared}

order by i.sort_order asc, i.id asc

select count(1) as total,
       coalesce(sum(case when i.prepared = 1 then 1 else 0 end), 0) as preparedCount
from preg_bag_item i
where i.del_flag = '0'

    and i.bag_id = #{bagId}


    and i.category = #{category}
